"""Execute review r2's fixed plans and its unchanged 400-case differentials."""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).parent))
import p2_drain as p
import p2b_diff as diff
from common import MODULES, DEEPER, patched

PLANS = [{}, {1:'KI'}, {1:'OS'}, {2:'KI'}, {1:'KI',2:'OS'}, {1:'OS',2:'KI'},
         {1:'KI',2:'KI'}, {1:'OS',2:'OS'}, {1:'KI',3:'OS'}, {2:'C',3:'KI'}, {1:'RT',2:'OS',3:'KI'}]

def test_33_walk_plans():
    for action in ('close','throw','list'):
        for plan in PLANS:
            out=[]
            for name in ('d3a','head'):
                m=MODULES[name]
                with patched(m,'MAX_DEPTH',3 if action=='list' else m.MAX_DEPTH):
                    out.append(p.walk_drain(m,DEEPER,0 if action=='list' else 5,plan,action))
            a,b=out
            assert not b['leaked'] and b['root_ok'], (action,plan,b)
            cancellation=next((kind for at,kind in sorted(plan.items()) if at <= b['closes'] and kind in ('KI','C')),None)
            if cancellation:
                assert b['caught'][0] == {'KI':'KeyboardInterrupt','C':'Custom'}[cancellation], (action,plan,b)
            elif action=='throw':
                assert b['caught'] == ('RuntimeError',None,None,'caller'), (action,plan,b)
            elif action=='list':
                assert b['caught'][:2] == ('TreeError','too-deep'), (action,plan,b)
            else:
                assert b['caught'] is None, (action,plan,b)
            if not plan or (action=='close' and len(plan)==1 and cancellation):
                assert a['caught'] == b['caught'], (action,plan,out)
    print('33 walk plans: precedence, ownership and single-failure parity passed')

def test_33_repository_plans():
    for git_at in (None,'a/b/c','a/b'):
        for plan in PLANS:
            a,b=[p.repo_drain(MODULES[name],DEEPER,'a/b/c',plan,True,git_at) for name in ('d3a','head')]
            assert not b['leaked'], (git_at,plan,b)
            assert a['caught'] == b['caught'] and a['value'] == b['value'], (git_at,plan,a,b)
    print('33 repository plans: precedence, ownership and single-failure parity passed')

def test_400_walk_differentials():
    diff.test_walk_same()
    assert diff.stats['cases']==400
    print('walk differentials',diff.stats)

def test_400_repository_differentials():
    diff.test_repo_same()
    assert diff.stats['repo']==400
    print('repository differentials',diff.stats)

