"""Scratch probe helpers for review r2 of #279; every tree is a temporary scratch tree."""
from __future__ import annotations

import contextlib
import errno
import fcntl
import os
import sys
import tempfile
import types
from pathlib import Path

HERE = Path(__file__).resolve().parent
WORKTREE = Path("/Users/maxghenis/.subfleet/worktrees/20261030-100933-pr279-fix-r3")
sys.path.insert(0, str(WORKTREE))

from subfleet import retention_fs as head  # noqa: E402


def load(name: str, path: Path):
    module = types.ModuleType(name)
    module.__file__ = str(path)
    sys.modules[name] = module
    exec(compile(path.read_text(), f"<{name}>", "exec"), module.__dict__)
    return module


d3a = load("rfs_d3a", HERE / "rfs_d3a.py")
base = load("rfs_base", HERE / "rfs_base.py")
MODULES = {"base": base, "d3a": d3a, "head": head}


def open_descriptors() -> set[int]:
    result = set()
    for name in os.listdir("/dev/fd"):
        if not name.isdigit():
            continue
        fd = int(name)
        try:
            fcntl.fcntl(fd, fcntl.F_GETFD)
        except OSError as exc:
            assert exc.errno == errno.EBADF
        else:
            result.add(fd)
    return result


@contextlib.contextmanager
def tree(entries):
    with tempfile.TemporaryDirectory(prefix="r2-probe-") as temporary:
        root = Path(temporary)
        for rel, kind in entries:
            path = root / rel
            if kind == "d":
                path.mkdir()
            elif kind == "l":
                path.symlink_to("missing")
            else:
                path.write_bytes(b"scratch")
        root_fd = os.open(root, os.O_RDONLY | os.O_DIRECTORY)
        try:
            yield root, root_fd
        finally:
            os.close(root_fd)


@contextlib.contextmanager
def patched(obj, attr, value):
    old = getattr(obj, attr)
    setattr(obj, attr, value)
    try:
        yield
    finally:
        setattr(obj, attr, old)


def describe(exc):
    if exc is None:
        return None
    return (type(exc).__name__, getattr(exc, "reason", None), getattr(exc, "errno", None), str(exc))


def chain(exc):
    out = []
    seen = set()
    while exc is not None and id(exc) not in seen:
        seen.add(id(exc))
        out.append(type(exc).__name__ + ":" + str(exc))
        exc = exc.__context__
    return " <- ".join(out)


DEEP = [("a", "d"), ("a/b", "d"), ("a/b/leaf", "f")]
DEEPER = [("a", "d"), ("a/b", "d"), ("a/b/c", "d"), ("a/b/c/leaf", "f")]

