"""Check 2: P2-2 at head (_close_all in walk and _in_repository), against d3a48269a on the same inputs."""
from __future__ import annotations

import errno
import os

from common import DEEP, DEEPER, MODULES, chain, describe, head, open_descriptors, patched, tree


class Custom(BaseException):
    pass


def exc_of(kind, n):
    return {"KI": KeyboardInterrupt(f"close {n}"), "OS": OSError(errno.EIO, f"close {n}"),
            "C": Custom(f"close {n}"), "RT": RuntimeError(f"close {n}")}[kind]


def walk_drain(module, entries, steps, plan, action, closed_first=True):
    """Advance walk `steps` times, then close/throw; the k-th close of a walk-opened descriptor raises plan[k]."""
    with tree(entries) as (root, root_fd):
        before = open_descriptors()
        opened = []
        real_open = module.open_dir

        def open_dir(*a, **k):
            fd = real_open(*a, **k)
            opened.append(fd)
            return fd

        real_close = os.close
        raised = []
        count = {"n": 0}

        def close(fd):
            if fd in opened:
                count["n"] += 1
                kind = plan.get(count["n"])
                if kind:
                    if closed_first:
                        real_close(fd)
                    e = exc_of(kind, count["n"])
                    raised.append(e)
                    raise e
            return real_close(fd)

        caught = None
        with patched(module, "open_dir", open_dir):
            iterator = module.walk(root_fd)
            for _ in range(steps):
                next(iterator)
            with patched(os, "close", close):
                try:
                    if action == "close":
                        iterator.close()
                    elif action == "throw":
                        iterator.throw(RuntimeError("caller"))
                    else:
                        list(iterator)
                except BaseException as e:  # noqa: BLE001
                    caught = e
        after = open_descriptors()
        leaked = after - before
        for fd in leaked:
            os.close(fd)
        try:
            os.fstat(root_fd)
            root_ok = True
        except OSError:
            root_ok = False
        first = raised[0] if raised else None
        return {"leaked": sorted(leaked), "caught": describe(caught), "is_first": caught is first and first is not None,
                "chain": chain(caught), "root_ok": root_ok, "closes": count["n"]}


def repo_drain(module, entries, rel, plan, closed_first=True, git_at=None):
    with tree(entries) as (root, root_fd):
        if git_at is not None:
            (root / git_at / ".git").mkdir()
        before = open_descriptors()
        opened = []
        real_open = module.open_dir

        def open_dir(*a, **k):
            fd = real_open(*a, **k)
            opened.append(fd)
            return fd

        real_close = os.close
        raised = []
        count = {"n": 0}

        def close(fd):
            if fd in opened:
                count["n"] += 1
                kind = plan.get(count["n"])
                if kind:
                    if closed_first:
                        real_close(fd)
                    e = exc_of(kind, count["n"])
                    raised.append(e)
                    raise e
            return real_close(fd)

        caught = None
        value = None
        with patched(module, "open_dir", open_dir), patched(os, "close", close):
            walker = module.RegenerableWalk(root_fd, lambda _: True)
            try:
                value = walker._in_repository(rel)
            except BaseException as e:  # noqa: BLE001
                caught = e
        after = open_descriptors()
        leaked = after - before
        for fd in leaked:
            os.close(fd)
        first = raised[0] if raised else None
        return {"leaked": sorted(leaked), "value": value, "caught": describe(caught),
                "is_first": caught is first and first is not None, "chain": chain(caught)}


if __name__ == "__main__":
    plans = [{}, {1: "KI"}, {1: "OS"}, {2: "KI"}, {1: "KI", 2: "OS"}, {1: "OS", 2: "KI"}, {1: "KI", 2: "KI"},
             {1: "OS", 2: "OS"}, {1: "KI", 3: "OS"}, {2: "C", 3: "KI"}, {1: "RT", 2: "OS", 3: "KI"}]
    print("== walk drain on a/b/c/leaf, advanced 5 times (stack: root, a, a/b, a/b/c)")
    for action in ("close", "throw"):
        for plan in plans:
            for closed_first in (True, False):
                row = {name: walk_drain(MODULES[name], DEEPER, 5, plan, action, closed_first) for name in ("d3a", "head")}
                h, d = row["head"], row["d3a"]
                same = h["caught"] == d["caught"]
                print(f"{action:5} plan={str(plan):30} closed_first={closed_first!s:5} "
                      f"head: leaked={h['leaked']} is_first={h['is_first']!s:5} caught={h['caught'] and h['caught'][:2]} "
                      f"root_ok={h['root_ok']} | d3a: leaked={d['leaked']} caught={d['caught'] and d['caught'][:2]} | same_exc={same}"
                      f" | chain=[{h['chain']}]")
    print()
    print("== walk drain during a full walk that fails (TreeError too-deep at MAX_DEPTH=3) with failing closes")
    for plan in plans:
        row = {}
        for name in ("d3a", "head"):
            m = MODULES[name]
            with patched(m, "MAX_DEPTH", 3):
                # the closes counted are of walk-opened descriptors; full traversal pops nothing before too-deep
                row[name] = walk_drain(m, DEEPER, 0, plan, "list")
        h, d = row["head"], row["d3a"]
        print(f"plan={str(plan):30} head: leaked={h['leaked']} caught={h['caught'] and h['caught'][:2]} chain=[{h['chain']}]"
              f" | d3a: leaked={d['leaked']} caught={d['caught'] and d['caught'][:2]} chain=[{d['chain']}]")
    print()
    print("== _in_repository drain (a/b/c) with failing closes, with and without .git")
    for git_at in (None, "a/b/c", "a/b"):
        for plan in plans:
            row = {name: repo_drain(MODULES[name], DEEPER, "a/b/c", plan, True, git_at) for name in ("d3a", "head")}
            h, d = row["head"], row["d3a"]
            print(f"git={str(git_at):6} plan={str(plan):30} head: leaked={h['leaked']} value={h['value']} "
                  f"caught={h['caught'] and h['caught'][:2]} is_first={h['is_first']!s:5} | d3a: leaked={d['leaked']} "
                  f"value={d['value']} caught={d['caught'] and d['caught'][:2]} | chain=[{h['chain']}]")

